  values (pid, 'The Quiet Hours', 'After her brother vanishes on a night drive, an insomniac radio host starts taking calls from listeners who swear they saw him — each one placing him somewhere different.', me, 'concept', '#c0392b', null, null, null,
          'Feature', '{"modules":{"lounge":true,"studio":true,"scriptos":true,"portfolio":true,"distribution":true},"contentType":"screenplay","demo":true}'::jsonb, '[]'::jsonb, 'team', null, (now() - interval '30240 minutes'));
