  select id into me from auth.users where lower(email) = lower(current_setting('demo.owner'));
  if me is null then raise exception 'No account for the demo.owner account'; end if;


  -- ── Night Shift at the Lantern ──
  pid := '3a949a0b-bed1-4dfa-ab39-1c73d8dc42f7';
  perform set_config('request.jwt.claims', json_build_object('sub', me, 'role', 'authenticated')::text, false);
