  insert into public.script_characters (script_id, name, full_name, age, description, motivation, arc, color, updated_by) values ('e30c1b53-3863-4238-afd8-030e7ed1dfe9', 'ELI', 'Elijah Moss', '74', 'Widower. Same stool since 1983.', 'One more night with the light on.', null, '#16a085', me);
