  values (pid, 'Paper Moons', 'A music video for Halcyon Tide’s “Paper Moons”: one singer, three hundred paper moons, and a city that won’t stay dark.', me, 'production', '#9b59b6', 4500, ((now() at time zone 'America/Edmonton')::date + -1), ((now() at time zone 'America/Edmonton')::date + 0),
          'Music Video', '{"modules":{"lounge":true,"studio":true,"scriptos":true,"portfolio":true,"distribution":true},"contentType":"screenplay","demo":true}'::jsonb, '[]'::jsonb, 'team', null, (now() - interval '44640 minutes'));
